import{c as p,Q as i,j as o,m as t}from"./chunks/framework.CHJbb1iY.js";const k=JSON.parse('{"title":"","description":"","frontmatter":{"outline":[2,3],"aside":"left"},"headers":[],"relativePath":"docs/笔记/面试复盘/面试复盘.md","filePath":"docs/笔记/面试复盘/面试复盘.md"}'),e={name:"docs/笔记/面试复盘/面试复盘.md"};function a(c,l,r,b,u,s){return i(),o("div",null,[...l[0]||(l[0]=[t('<h1 style="text-align:center;">面试复盘</h1><h2 id="_5-15-勤思科技一面" tabindex="-1">5.15（勤思科技一面） <a class="header-anchor" href="#_5-15-勤思科技一面" aria-label="Permalink to &quot;5.15（勤思科技一面）&quot;">​</a></h2><p>项目：天机学堂</p><p>面试时间：17 分钟，拷打项目，无反问环节</p><p>面试岗位：全栈开发实习生（会使用 AI 工具）</p><p>面试过程</p><ol><li><p>自我介绍</p></li><li><p>项目是自己做的吗？项目情况</p></li><li><p>说一下你开发的模块，开发中遇到的问题，如何解决的？</p></li><li><p>redis 宕机，服务断开，如何保证数据不丢失</p><blockquote><p>八股：<strong>redis 的持久化策略</strong>，这块不熟</p></blockquote></li><li><p>队列信息保存失败了，数据丢失如何解决？</p><blockquote><p>八股：<strong>消息丢失如何解决，可靠性如何保障</strong>，这块不了解</p></blockquote></li><li><p>数据库又遇到查询慢的问题慢，索引问题，死锁问题等，谈谈对数据库的理解</p><blockquote><p>回答了索引失效的排查流程，死锁暂时没有遇到</p></blockquote></li><li><p>谈谈对 RabbitMQ 的理解和底层</p><blockquote><p>不会，回答了消息队列的结构</p></blockquote></li><li><p>聊一聊其他模块</p><blockquote><p>点赞模块</p></blockquote></li><li><p>谈一谈 Redis 中 set 和 sortedset 的底层结构</p></li><li><p>项目开发过程中有遇到什么报错的问题</p><blockquote><p>这里没有遇到，转向遇到比较难的问题，谈到了优惠卷模块的锁问题</p></blockquote></li><li><p>读写锁和共享锁的差异是什么？</p></li><li><p>还有其他模块吗？</p><blockquote><p>提到了 SpringAI</p></blockquote></li><li><p>你现在是大二，有跟老师去做过项目吗？</p><blockquote><p>提到自己组织同学开发，模拟企业级开发流程</p></blockquote></li><li><p>说一下你是如何设计数据库的</p><blockquote><p>没有提到产品原型</p></blockquote></li><li><p>如果有一个登录模块让做，说一下你会设计哪些表？</p><blockquote><p>这里还是被问住了，答的不是很好</p></blockquote></li></ol><h2 id="_5-15-城安物联科技" tabindex="-1">5.15（城安物联科技） <a class="header-anchor" href="#_5-15-城安物联科技" aria-label="Permalink to &quot;5.15（城安物联科技）&quot;">​</a></h2><p>项目：天机学堂</p><p>面试时间：9 分钟（hr 面），有反问环节</p><p>面试岗位：智能体开发</p><p>面试过程</p><ol><li><p>介绍项目经历</p></li><li><p>项目中扮演的是什么角色？是自己开发的吗？</p></li><li><p>项目中遇到什么问题，都是怎么解决的？</p></li><li><p>实现这些功能有没有用到 AI 辅助编程</p></li><li><p>项目这个教育平台支持最大的在线人数是多少</p><blockquote><p>被问住了，回答了一万</p></blockquote></li><li><p>项目是学校的课题吗？</p></li><li><p>项目是否有可以展示的一些案例，发给 hr</p></li><li><p>反问环节</p><blockquote><ol><li>公司业务内容</li><li>面试表现如何，是否有可以提升的点</li></ol></blockquote></li></ol><p>面试反馈：自我介绍需要突出亮点，比较在行的这一块，可以着重介绍一些 AI 相关的（vibecoding），可以吸引面试官</p><h2 id="_5-16-深圳超曲速" tabindex="-1">5.16（深圳超曲速） <a class="header-anchor" href="#_5-16-深圳超曲速" aria-label="Permalink to &quot;5.16（深圳超曲速）&quot;">​</a></h2><p>项目：天机学堂 + 中州养老</p><p>面试时间：18 分钟，有反问环节</p><p>面试岗位：后端开发</p><p>面试过程</p><ol><li><p>自我介绍</p></li><li><p>学校学过什么编程语言</p></li><li><p>项目是自己的吗？</p></li><li><p>简单说一下乐享养老，你负责了什么</p></li><li><p>简单说一下对 RBAC 的理解</p></li><li><p>接了华为云的 iot，简单说一下数据采集是这么做的</p></li><li><p>项目中有没有让你印象比较深刻的事情，还有没有其他的</p><blockquote><p>优惠卷 + 视频续播</p></blockquote></li><li><p>mq 用的是哪一个</p></li><li><p>说一下对 Few-shot Prompting 的理解</p></li><li><p>项目开发过程中与其他人配合有没有什么心得，遇到什么的问题</p></li><li><p>你明年毕业，为什么现在想找实习啊</p></li><li><p>评价一下自己的学习能力</p></li><li><p>和他人协作过程中，有可能是自己或者其他项目组成员有 delay，你会如何处理与沟通</p></li><li><p>你觉得你的抗压能力怎么样</p></li><li><p>你怎么评价你自己，你觉得你是一个怎样的人</p></li><li><p>反问环节</p><blockquote><ol><li>公司业务内容</li><li>面试表现如何，是否有可以提升的点</li></ol></blockquote></li></ol><h2 id="_5-22-广东上视科技" tabindex="-1">5.22（广东上视科技） <a class="header-anchor" href="#_5-22-广东上视科技" aria-label="Permalink to &quot;5.22（广东上视科技）&quot;">​</a></h2><h3 id="vibecoding" tabindex="-1">vibecoding <a class="header-anchor" href="#vibecoding" aria-label="Permalink to &quot;vibecoding&quot;">​</a></h3><p>项目：无</p><p>面试时间：15 分钟，无反问环节</p><p>面试岗位：VibeCoding</p><p>面试过程</p><ol><li><p>自我介绍</p></li><li><p>用过哪些工具</p></li><li><p>用 ClaudeCode 实现一个需求：科技新闻聚合平台，手搓 prompt 展示</p></li></ol><h3 id="java-后端电话面" tabindex="-1">Java 后端电话面 <a class="header-anchor" href="#java-后端电话面" aria-label="Permalink to &quot;Java 后端电话面&quot;">​</a></h3><p>项目：无</p><p>面试时间：25 分钟，拷打八股，项目没问，无反问环节</p><p>面试岗位：Java 后端开发</p><p>面试过程</p><ol><li><p>自我介绍</p></li><li><p>说一下 JVM 的垃圾回收算法</p></li><li><p>为什么需要使用 ConcurrentHashMap，如何确保线程安全，解释一下</p></li><li><p>项目没有 Redis，如何实现缓存</p></li></ol><blockquote><p>回答了使用集合</p></blockquote><ol start="5"><li>集合存数据，涉及存储空间问题，JVM 内存空间只有 2 M，如果数据量很大，该如何解决？</li></ol><blockquote><p>回答了数据结构设计，分段存储，定义集合初始值</p></blockquote><ol start="6"><li><p>如何定义集合的初始值？</p></li><li><p>讲一下 Springboot 和 SpringMVC 的区别</p></li></ol><blockquote><p>提到了一些注解</p></blockquote><ol start="8"><li>讲一下 @Resstcontroller 和 @Controller 的区别</li></ol><blockquote><p>不了解，换一个更简单的，这里没绷住</p></blockquote><ol start="9"><li>讲一下 @Resource 和 @Autowired 的区别</li></ol><blockquote><p>不了解，真没绷住</p></blockquote><ol start="10"><li><p>你平常用什么数据库</p></li><li><p>MySQL 最左匹配原则是什么意思？解释一下</p></li><li><p>讲一下 MySQL 的事务隔离级别</p></li></ol><blockquote><p>这里忘记了几个，没说出来，尬住了</p></blockquote><ol start="13"><li>数据写入 MySQL 失败，如何解决数据不丢失的问题？</li></ol><blockquote><p>提到了 redolog</p></blockquote><ol start="14"><li><p>如何调用 MySQL 的操作日志？不可以使用命令调用查看吗？</p></li><li><p>有了解过前端吗？</p></li><li><p>说一下 vue 的生命周期</p></li><li><p>知道懒加载吗？</p></li><li><p>懒加载延长了渲染时间，如何实现实时性加载？</p></li></ol><blockquote><p>提到了缓存到浏览器</p></blockquote><ol start="19"><li><p>不同浏览器怎么处理？没有 oss 存储怎么办？</p></li><li><p>之前有实习经历吗？</p></li><li><p>聊了一下，注重开发实践，如何解决问题，而不是理论内容</p></li><li><p>人在哪？</p></li><li><p>vibecoding 岗位已经找到合适的人选，boss 上还没更新后端实习生岗位，简历被人事推送到后端部门，还是第一个</p></li><li><p>你的期望薪资多少？</p></li></ol><blockquote><p>这里问了对方最低能给到多少，没绷住</p></blockquote><ol start="25"><li>今天是电话面试，主要还是了解一下情况，简历的描述和真实水平是否符合，如果合适会有二轮技术面需要线下面试，不会问很难的内容</li></ol><h2 id="_5-26-广州竟采星" tabindex="-1">5.26（广州竟采星） <a class="header-anchor" href="#_5-26-广州竟采星" aria-label="Permalink to &quot;5.26（广州竟采星）&quot;">​</a></h2><p>项目：天机学堂 + 中州养老</p><p>面试时间：30 分钟，拷打项目，有反问环节</p><p>面试岗位：软件工程师</p><p>内心 OS：三人视频面，全程被压力，以 27 届身份面试，大多内容不真实，真绷不住</p><p>面试过程</p><ol><li><p>自我介绍</p></li><li><p>27 年毕业？有实习过吗？哪里人？</p></li><li><p>在校期间获得了一些奖，含金量最高的是哪个？学校成绩怎么样？年级多少人？</p></li><li><p>共享屏幕展示一下自己的项目</p></li></ol><blockquote><p>这里直接傻了，巨紧张，找了很久没找到，加上还是黑马大弟子，这里僵持了 3 分钟直接口述了</p></blockquote><ol start="5"><li><p>AI 这块有接触吗？学习过程中感觉自己有哪些不足的地方，比较弱或者需要加强的地方？</p></li><li><p>你觉得你这个人最大的优势是什么？</p></li><li><p>Redis 宕机了，如何确保数据不丢失？</p></li></ol><blockquote><p>问了几次了还是没答好，在准备一下 8. 具体说一下对接大模型的过程</p></blockquote><ol start="9"><li><p>天机学堂中的智能体主要处理哪方面的问题？</p></li><li><p>介绍一下 Few-shot Prompting</p></li></ol><blockquote><p>问了几次了还是没答好，在准备一下</p></blockquote><ol start="11"><li><p>如果你要 AI 输出一个固定格式的 json 数据，你会怎么写 prompt？</p></li><li><p>谈谈你对 Springboot 和 SpringCloud 的理解</p></li></ol><blockquote><p>这里很紧张，没答好</p></blockquote><ol start="13"><li><p>Mybatis-Plus 有用吗？ 分页查询具体怎么查？（代码层面的）</p></li><li><p>中州养老提到了 pdf 内容提取，有图片吗？如果有图片你怎么处理？</p></li><li><p>我看你是软件工程，你们学校主要学习什么课程？</p></li><li><p>你的成绩在班上排名左右，班级有多少人？</p></li><li><p>英语六级是什么时候考的？</p></li><li><p>在学习过程中，你哪方面比较擅长？</p></li><li><p>你提到了 AI，这块你是如何学习的？</p></li><li><p>有没有跟同学开展一些学习的交流？</p></li><li><p>这两个项目的来源？自己练手的还是真实的？</p></li><li><p>你说是与同学协作项目？都是同班同学吗？</p></li><li><p>你现在这个课程学完没有？没有学完怎么实习？没学完怎么办呢？你还差多少课程？</p></li><li><p>如果让你来实习，多久到岗？</p></li><li><p>你现在在哪？像你这样出去实习的同学多不多？</p></li><li><p>你为什么不在学校附近找，要来广州？</p></li><li><p>你是否了解我们公司的业务？</p></li><li><p>对你来我们是欢迎的，广州这边你有地方住吗？</p></li></ol><blockquote><p>这里编说有亲戚在广州，面试官震惊说不是离公司很远，提到可以租房</p></blockquote><ol start="29"><li>你有什么东西需要了解的？</li></ol><blockquote><p>面试官给出了学习和技术上的客观评价，提到重点还是招正职，不过也给出了一定的认可</p></blockquote>',69)])])}const n=p(e,[["render",a]]);export{k as __pageData,n as default};
